using System;
using System.Collections.Generic;
using UnityEditor;

namespace KnockRush.EditorTools.Characters
{
    /// <summary>
    /// Import rules for every character FBX under Assets/Art/Characters/ (generated by
    /// ArtSource/Characters/build_bean.py): Generic rig, axis conversion baked, no imported
    /// materials (we use the KnockRush/Toon shader), clips renamed from "BeanRig|Idle" to "Idle"
    /// and looping set for cyclic clips.
    /// </summary>
    public sealed class CharacterModelPostprocessor : AssetPostprocessor
    {
        private const string CharactersFolder = "Assets/Art/Characters/";

        public static readonly HashSet<string> LoopingClips = new HashSet<string>(StringComparer.Ordinal)
        {
            "Idle", "Walk", "Run", "Fall", "Stumble", "Grab", "Celebrate", "VictoryDance",
            "Wave", "Bounce", "Spin", "Clap", "Bow", "Flex", "Laugh", "RobotDance"
        };

        private bool IsCharacterModel =>
            assetPath.StartsWith(CharactersFolder, StringComparison.Ordinal) &&
            assetPath.EndsWith(".fbx", StringComparison.OrdinalIgnoreCase);

        private void OnPreprocessModel()
        {
            if (!IsCharacterModel)
            {
                return;
            }

            var importer = (ModelImporter)assetImporter;
            importer.globalScale = 1f;
            importer.useFileScale = true;
            importer.bakeAxisConversion = true;
            importer.importCameras = false;
            importer.importLights = false;
            importer.importVisibility = false;
            importer.importBlendShapes = false;
            importer.materialImportMode = ModelImporterMaterialImportMode.None;
            importer.isReadable = false;
            importer.meshCompression = ModelImporterMeshCompression.Off;
            importer.animationType = ModelImporterAnimationType.Generic;
            importer.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
            importer.optimizeGameObjects = false;
            importer.importAnimation = true;
            importer.animationCompression = ModelImporterAnimationCompression.Optimal;
        }

        private void OnPreprocessAnimation()
        {
            if (!IsCharacterModel)
            {
                return;
            }

            var importer = (ModelImporter)assetImporter;
            var clips = importer.defaultClipAnimations;
            var result = new List<ModelImporterClipAnimation>(clips.Length);

            foreach (var clip in clips)
            {
                var name = clip.takeName;
                var separator = name.LastIndexOf('|');
                if (separator >= 0)
                {
                    name = name.Substring(separator + 1);
                }

                clip.name = name;
                clip.loopTime = LoopingClips.Contains(name);
                clip.loopPose = false;
                clip.lockRootRotation = false;
                clip.lockRootHeightY = false;
                clip.lockRootPositionXZ = false;
                result.Add(clip);
            }

            importer.clipAnimations = result.ToArray();
        }
    }
}
